import{bT as galleryKeywordSchema}from"./core-WbteBybW.js";const metadata=new WeakMap;function rememberWorldGalleryKeywords(target,raw,input){const field=galleryKeywordSchema(input);if(!field)return target;if(!Array.isArray(raw)||raw.length>5||raw.some(word=>typeof word!=="string"||!field.items.enum.includes(word))){throw Object.assign(Error("阅片关键词须从当前词库选择，最多5项"),{code:"world_shot_preparation"})}metadata.set(target,[...new Set(raw)]);return target}function worldGalleryKeywords(target){return[...metadata.get(target)||[]]}function carryWorldGalleryKeywords(target,source){metadata.set(target,worldGalleryKeywords(source));return target}export{carryWorldGalleryKeywords as c,rememberWorldGalleryKeywords as r,worldGalleryKeywords as w};
